  for (int i = 1; i < n; i++) {
    for (int j = 1; j <= n - i; j++) {
      if ((i + j > n && i % 2 == 0 && j % 2 == 1) || 
          (i + j > n && i % 2 == 1 && j % 2 == 0)) {
        collisions++;
      } else if (i != n - 1 && j != n - 1) {
        continue;
      }
    }
  }

  return collisions * 4;
}

