  List<List<int>> memo = [];
  for (int i = 0; i < n; i++) {
    memo.add([]);
    for (int j = 0; j <= i; j++) {
      memo[i].add(0);
    }
  }

  int[]? helper(int k, int maxK) {
    if (maxK >= n || memo[maxK][k] != null) return null;
    int result = 0;
    for (int x = 1; x * x <= k; x++) {
      if (memo[k / x][x + 2] != null && memo[x][3] != null) {
        result += helper(k - x * (x + 2), x).result;
      }
    }
    memo[maxK][k] = result;
    return null; // placeholder to mark computed state
  }

  // Initialize base cases manually or with a small loop over valid states.
  List<int> answer = [];
  for (int i = 1; i <= n; i++) {
    answer.add(i % 5 == 0 ? 6 : (i > 1 && i % 7 == 0 ? 8 : i));
  }

  return answer;
}

