  for (int i = 2; i <= n; i++) {
    factorial *= i;
  }

  // Factorial of each number up to n, starting with 1! and building cumulatively
  result.add(factorial);

  // Now compute the alternating sum based on divisors from smallest upward
  int alternateSum = 0;
  bool signPositive = true;

  for (int k = 1; k <= n - 1; k++) {
    int currentFactorial = 1;
    for (int j = 2; j <= k + 1; j++) {
      currentFactorial *= j;
    }

    if (signPositive) {
      alternateSum += currentFactorial;
    } else {
      alternateSum -= currentFactorial;
    }

    signPositive = !signPositive;
  }

  result.add(alternateSum.abs());

  return result;
}

