  int result = 0;
  for (int i = 0; i < n - 1; ++i) {
    final prev = f(n - 2);
    List<int> sumLine = [];
    for (int j = 0; j < n; ++j) {
      final left = (i > j ? prev[j] : 0);
      final right = (j + 1 >= prev.length ? 0 : prev[j + 1]);
      sumLine.add(left + right);
    }
    result += sumLine.reduce((a, b) => a * b);
  }

  if (result % n != 0) {
    throw StateError('No solution exists');
  } else {
    return sumLine.map((x) => x / n).toList();
  }
}

