List<int> f(int n) {
  final List<int> result = [];

  // Add the first element: always 1.
  if (n > 0) {
    result.add(1);
  } else {
    return result;
  }

  int current = 2, factorial = 1;

  for (int i = 1; i <= min(n, 4); i++) {
    factorial *= current++;
    result.add(factorial);
  }

  // After adding up to 4 terms, start generating new values using the recurrence relation.
  while (result.length < n && result.isNotEmpty) {
    var lastTwo = result.sublist(result.length - 2, result.length).toList();

    // If we have less than two elements yet, just append next term as per pattern manually.
    if (lastTwo.isEmpty || lastTwo[0] == null) continue;

    int sumOfLastThree = lastTwo.reduce((a,b)=>a+b)+result[result.length-3];
    int lastElement = result.last;
    int newValue = lastElement * sumOfLastThree / lastTwo.sum;

    result.add(newValue.round());
  }

  return result.take(n).toList();
}

List<int> f(int n) {
  List<int> primes = [];

  for (int i = 2; i <= n; i++) {
