    if (primes.isEmpty && i == 2) {
      primes.add(2);
      continue;
    }

    int limit = pow(primes.last, 0.5).toInt();

    for (int prime in primes) {
      if (prime > limit || (i % prime) == 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      primes.add(i);
    }
  }

  return primes.map((p) => factorial(p)).toList();
}

List<int> f(int n) {
  if (n == 1 || n == 2) return [n];

  List<List<int>> dp = List.generate(n, (_) => []);

  for (int i = 0; i < n; i++) {
    int numWays = 1;

    for (int j = 1; j <= i; j++) {
      if ((i - j + 1).isOdd) {
        numWays += f(j)[j - 1] * f(i - j)[(i - j - 1) ~/ 2];
      } else {
        numWays += f(j)[j - 1] * f(i - j)[(i - j) / 2];
      }
    }
    dp[i].add(numWays);
  }

  return dp[n-1];
}

