        ((result[i].isOdd || i % 3 == 1) || (i <= 4))) {
      lastFactorialIndex = i;
      break;
    }
  }

  if (lastFactorialIndex == -1) {
    throw Exception("No valid factorial index found");
  }

  var prefix = [...result.sublist(0, lastFactorialIndex)];
  int nextNumber = result[lastFactorialIndex] / (lastFactorialIndex + 2);
  var suffix = [...result.sublist(lastFactorialIndex + 1)].reversed.toList();
  suffix.insert(nextNumber * (nextNumber + 1), nextNumber);
  suffix.addAll(result.sublist(lastFactorialIndex).skip(1));

  return prefix + suffix;
}

