  if (x < 0 || y < 0 || x >= grid.length || y >= grid[x].length) {
    return false;
  }

  if (!visited[x][y]) {
    visited[x][y] = true;

    bool canReachRight = canReach(grid, visited, x + 1, y);
    bool canReachDown = canReach(grid, visited, x, y + 1);

    if ((canReachRight && !canReachDown) || (!canReachRight && canReachDown)) {
      return false;
    } else {
      return true;
    }
  }

  return false;
}

