int maxFill(List<List<int>> grid, int capacity) {
  var result = 0;

  for (var i = 0; i < grid.length; i++) {
    List<bool> visitedRow = [false] * grid[i].length; // Track which cells in the row have been filled

    for (var j = 0; j < grid[0].length; j++) {
      if (!visitedRow[j]) {
        var stack = [];

        for (var k = i; k >= 0 && !grid[k][j]; k--) {} // Find topmost empty cell

        while (k >= 0 && grid[k][j]) {
          stack.add(k);
          k--;
        }

        if (stack.isEmpty || capacity == 0) continue;

        while (capacity > 0 && stack.isNotEmpty) {
          var r = stack.removeAt(0); // Pop from bottom of stack (top of water column)

          // Check left and right neighbors for potential overflow
          bool canOverflowLeft = false;
          bool canOverflowRight = false;

          int colStart = j - 1;
          int colEnd = j + 1;

          if (colStart >= 0) {
            canOverflowLeft = true;
            for (var c = colStart; c <= colEnd; c++) {
              if (c < 0 || c >= grid[r].length) continue;

              if (grid[r][c] == 0) break; // Found an open space below this wall

              if (r == 0) break; // Reached top boundary

              int nextR = r - 1;
              if (nextR >= 0 && grid[nextR][c] != 0) continue; // Wall exists above

              bool hasWallAbove = false;
              for (var nc = c-1; nc <= c+1; nc++) {
                if (nc < 0 || nc >= grid[r].length) continue;

                if (grid[r][nc] == 0) continue; // Open space means no continuous wall

                hasWallAbove = true;
                break;
              }

              if (!hasWallAbove) break;
            }

            if (!canOverflowLeft) break;
          } else {
            // No valid path to the left edge
            break;
          }

          if (capacity > 0) {
            result += 1;
            capacity -= 1;
          }
        }

        if (result >= grid.length * grid[0].length) return result;
      }
    }
  }

  return result;
}

