  // Function to fill the cells in a given direction (up, down, left, right).
  void fillCells(int row, int col, List<List<int>> directions) {
    for (var i = 0; i < directions.length; i++) {
      var newRow = row + directions[i][0];
      var newCol = col + directions[i][1];
      if (newRow >= 0 && newRow < grid.length && 
          newCol >= 0 && newCol < grid[0].length && !isFilled(newRow, newCol)) {
        grid[newRow][newCol] = 1;
        fillCells(newRow, newCol, directions);
      }
    }
  }

  // Directions: up, down, left, right.
  const List<List<int>> directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  int count = 0;
  List<bool> visited = List.filled(grid.length, false);

  // Start from each unfilled cell and fill it using DFS.
  for (int i = 0; i < grid.length; i++) {
    visited[i] = true;
    if (!isFilled(i, 0)) {
      fillCells(i, 0, directions);
      count++;
    }
  }

  // Return the number of filled cells.
  return count * capacity;
}

