    for (var j = 0; j < grid[i].length; j++) {
      if (grid[i][j] == 1 && filledCount < capacity - 1) {
        continue;
      } else if (filledCount >= capacity - 1 || grid[i][j] == 0) {
        if (grid[i][j] != 0) {
          filledCount++;
        }

        // Check if we can fill the next cell in the same row or column without exceeding capacity.
        bool foundNextCellInRowOrColumn = false;

        for (int k = j + 1; k < grid[i].length; k++) {
          if (grid[i][k] != 0) {
            foundNextCellInRowOrColumn = true;
            break;
          }
        }

        if (!foundNextCellInRowOrColumn) {
          for (int m = i + 1; m < grid.length; m++) {
            if (grid[m][j] != 0) {
              foundNextCellInRowOrColumn = true;
              break;
            }
          }

          if (!foundNextCellInRowOrColumn) {
            while (i > 0 && grid[i-1][j] == 0) i--;

            while (j > 0 && grid[i][j-1] == 0) j--;
          }
        }
      }

      if (grid[i][j] == 0) {
        if ((i > 0 && grid[i-1][j] == 1) || (j > 0 && grid[i][j-1] == 1)) {
          continue;
        }

        grid[i][j] = 1;
        filledCount++;
      }
    }

    if (filledCount >= capacity) break;
  }

  return filledCount;
}

