int maxFill(List<List<int>> grid, int capacity) {
  final n = grid.length;
  if (n == 0 || n == 1 && grid[0].isEmpty) return 0;

  // Compute prefix sums for each row.
  List<List<int>> prefRows = [];
  for (var i = 0; i < n; i++) {
    var row = grid[i];
    var acc = [row[0]];
    for (var j = 1; j < row.length; j++) {
      acc.add(acc[j - 1] + row[j]);
    }
    prefRows.add(acc);
  }

  // Try all possible starting rows and ending columns.
  int best = 0;
  for (int startRow = 0; startRow < n; startRow++) {
    for (int endCol = 0; endCol <= prefRows[startRow][prefRows[startRow].length - 1]; endCol++) {
      int sum = 0;
      int curEndCol = endCol;
      for (int r = startRow; r >= 0; r--) {
        // Move left as long as we can while keeping the rectangle height ≤ capacity.
        int widthUsed = curEndCol;
        bool ok = true;
        for (int c = curEndCol; c > 0 && widthUsed > capacity; c--, widthUsed--) {
          if (r == 0) break;
          widthUsed += prefRows[r - 1][c - 1] - prefRows[r - 1][curEndCol];
          if (widthUsed > capacity) ok = false;
        }
        if (!ok) break;
        sum += curEndCol;
        curEndCol--;
      }
      if (sum > best) best = sum;
    }
  }

  return best;
}

