  bool hasDuplicates = false;
  Map<int, int> counts = {};
  for (int value in lst) {
    counts[value] = (counts[value] ?? 0) + 1;
    if (counts[value] > 2) hasDuplicates = true;
  }

  if (hasDuplicates || min == max) return [null, null];

  // Calculate distance between min and max
  int rangeLength = max - min;
  int distanceBetweenMinAndMax = rangeLength / 3;

  List<int>? sortedLst = [...lst].toList();
  sortedLst.sort((a, b) => a.compareTo(b));
  int minIndex = sortedLst.indexOf(min);
  int maxIndex = sortedLst.indexOf(max);

  // Determine which end is closer to both extremes
  int closestEndToBothExtremes = (minIndex <= maxIndex) 
      ? maxIndex - minIndex >= distanceBetweenMinAndMax ? "left" : "right"
      : maxIndex - minIndex < distanceBetweenMinAndMax ? "left" : "right";

  if (closestEndToBothExtremes == 'left') return [-max, -(min - 1)];
  else return [-min, max - 1];
}

