List<int> orderByPoints(List<int> nums) {
  if (nums.isEmpty) return [];

  int minIndex = 0;
  for (int i = 1; i < nums.length - 1; i++) {
    if (nums[i] > nums[minIndex]) {
      minIndex = i;
    } else {
      break; // Exit early since array is sorted ascendingly
    }
  }

  List<List<int>> groups = [[], []];
  int leftStartIndex = minIndex + 1, rightEndIndex = nums.length - 1;

  while (leftStartIndex <= rightEndIndex) {
    if (nums[leftStartIndex] >= 0 && nums[rightEndIndex] >= 0) {
      groups[0].add(nums[leftStartIndex]);
      groups[1].insert(0, nums[rightEndIndex]);
      leftStartIndex++;
      rightEndIndex--;
    } else if (nums[leftStartIndex] < 0) {
      groups[1].insert(0, nums[leftStartIndex]);
      leftStartIndex++;
    } else {
      groups[0].add(nums[rightEndIndex]);
      rightEndIndex--;
    }
  }

  List<int> result = [...groups[0], ...nums.sublist(minIndex), ...groups[1]];
  return result;
}

