  while (left <= right) {
    if (sorted[left].length == sorted[right].length) {
      // If lengths match, sum them and add to result.
      String sumString = sorted[left] + sorted[right];
      result.add(sumString);
      left++;
      right--;
    } else if (sorted[left].length < sorted[right].length) {
      // Move left pointer forward since it's shorter.
      left++;
    } else {
      // Move right pointer backward since it's longer.
      right--;
    }
  }

  return result;
}

